namespace AnyCli.Parameters.Options;

/// <summary>
/// Describes how typed global options are configured and created.
/// </summary>
/// <typeparam name="TSelf">The global options type.</typeparam>
/// <remarks>
/// Implementations are normally generated by the AnyCli source generator from
/// <see cref="GlobalOptionsAttribute"/> and <see cref="OptionAttribute"/> members.
/// </remarks>
public interface IGlobalOptions<TSelf>
    where TSelf : class, IGlobalOptions<TSelf>
{
    /// <summary>
    /// Defines the global options.
    /// </summary>
    /// <param name="options">The global options builder.</param>
    static abstract void Configure(GlobalOptionBuilder options);

    /// <summary>
    /// Creates typed global options from parsed option values.
    /// </summary>
    /// <param name="values">The parsed option values.</param>
    /// <returns>The global options instance.</returns>
    static abstract TSelf Bind(CommandOptionValues values);
}
